#include <stdio.h>

int is_leap(int year) {
    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
}

int main() {
    printf("%d %d %d\n", is_leap(1900), is_leap(2000), is_leap(2024));
    return 0;
}
